"""query_library/calidad_v3.py — 50 consultas adicionales de Calidad (v3)."""
from backend.modules.db_simulator.query_library.builder import q
QUERIES_CALIDAD_V3: list = [
    q("cv3_001","Tasa de devoluciones por familia","¿Qué familias tienen mayor tasa de devolución?","Ratio abonos/ventas por familia.","SELECT F.NOMBRE AS FAMILIA, ROUND(SUM(CASE WHEN D.TIPO=13 THEN L.CANTIDAD*L.PRECIO ELSE 0 END),2) AS VENTAS, ROUND(SUM(CASE WHEN D.TIPO=14 THEN L.CANTIDAD*L.PRECIO ELSE 0 END),2) AS DEVOLUCIONES FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO LEFT JOIN ARTICULO A ON A.CODIGO=L.CODARTICULO LEFT JOIN FAMILIA F ON F.CODIGO=A.CODFAMILIA WHERE D.TIPO IN (13,14) GROUP BY F.NOMBRE HAVING DEVOLUCIONES>0 ORDER BY DEVOLUCIONES DESC LIMIT 15","Calidad","Calidad","KPI","Alto","Devoluciones",""),
    q("cv3_002","Artículos con mayor número de abonos","¿Qué artículos generan más abonos?","Artículos con más líneas en TIPO=14.","SELECT L.CODARTICULO AS COD_ART, A.NOMBRE, COUNT(*) AS N_ABONOS, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS IMPORTE FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO LEFT JOIN ARTICULO A ON A.CODIGO=L.CODARTICULO WHERE D.TIPO=14 GROUP BY L.CODARTICULO, A.NOMBRE ORDER BY N_ABONOS DESC LIMIT 20","Calidad","Calidad","Alerta","Alto","Devoluciones",""),
    q("cv3_003","Evolución de devoluciones por mes","¿Cómo evoluciona el importe de devoluciones mes a mes?","Abonos TIPO=14 por mes.","SELECT SUBSTR(D.FECHA,1,7) AS MES, COUNT(DISTINCT D.CODIGO) AS N_ABONOS, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS IMPORTE FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO WHERE D.TIPO=14 AND D.FECHA>=DATE('now','-365 days') GROUP BY SUBSTR(D.FECHA,1,7) ORDER BY MES DESC","Calidad","Calidad","KPI","Alto","Devoluciones",""),
    q("cv3_004","Clientes con mayor importe de devoluciones","¿Qué clientes devuelven más mercancía?","Clientes con mayor importe en abonos TIPO=14.","SELECT D.CODCLIENTE, COALESCE(C.NOMBRECOMERCIAL,C.RAZONSOCIAL) AS CLIENTE, COUNT(DISTINCT D.CODIGO) AS N_ABONOS, ROUND(SUM(L.CANTIDAD*L.PRECIO),2) AS IMPORTE FROM DOCCAB D JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO LEFT JOIN CLIENTE C ON C.CODIGO=D.CODCLIENTE WHERE D.TIPO=14 GROUP BY D.CODCLIENTE, CLIENTE ORDER BY IMPORTE DESC LIMIT 20","Calidad","Calidad","Alerta","Alto","Devoluciones",""),
    q("cv3_005","Artículos con STOCKARTICULO bajo mínimo","¿Qué artículos tienen STOCKARTICULO por debajo del mínimo?","Artículos con STOCKARTICULO actual inferior al STOCKARTICULO mínimo definido.","SELECT A.CODIGO, A.NOMBRE, ROUND(SUM(A.STOCKARTICULO),2) AS STOCK_ACTUAL, A.STOCKARTICULO FROM ARTICULO A JOIN ESTALMACEN E ON A.CODIGO=A.CODIGO WHERE A.STOCKARTICULO>0 GROUP BY A.CODIGO, A.NOMBRE, A.STOCKARTICULO HAVING STOCK_ACTUAL<A.STOCKARTICULO ORDER BY (A.STOCKARTICULO-STOCK_ACTUAL) DESC LIMIT 25","Calidad","Calidad","Alerta","Critico","STOCKARTICULO",""),
    q("cv3_006","Artículos con STOCKARTICULO negativo","¿Existen artículos con STOCKARTICULO negativo?","Artículos con STOCKARTICULO total negativo en almacén.","SELECT A.CODIGO, A.NOMBRE, ROUND(SUM(A.STOCKARTICULO),2) AS STOCK_TOTAL FROM ARTICULO A JOIN ESTALMACEN E ON A.CODIGO=A.CODIGO GROUP BY A.CODIGO, A.NOMBRE HAVING STOCK_TOTAL<0 ORDER BY STOCK_TOTAL ASC LIMIT 20","Calidad","Calidad","Alerta","Critico","STOCKARTICULO",""),
    q("cv3_007","Facturas con importe cero o negativo","¿Existen facturas con importe anómalo?","Facturas TIPO=13 con importe total cero o negativo.","SELECT D.CODIGO, D.FECHA, D.CODCLIENTE, ROUND(SUM(COALESCE(L.CANTIDAD*L.PRECIO,0)),2) AS IMPORTE FROM DOCCAB D LEFT JOIN DOCLIN L ON L.CODDOCUMENTO=D.CODIGO WHERE D.TIPO=13 GROUP BY D.CODIGO, D.FECHA, D.CODCLIENTE HAVING IMPORTE<=0 ORDER BY D.FECHA DESC LIMIT 20","Calidad","Calidad","Alerta","Critico","Anomalías",""),
    q("cv3_008","Facturas sin líneas de detalle","¿Existen facturas sin ninguna línea de detalle?","Facturas TIPO=13 sin líneas en DOCLIN.","SELECT CODIGO, FECHA, D.CODCLIENTE FROM DOCCAB D WHERE D.TIPO=13 AND CODIGO NOT IN (SELECT DISTINCT CODDOCUMENTO FROM DOCLIN) ORDER BY FECHA DESC LIMIT 20","Calidad","Calidad","Alerta","Critico","Anomalías",""),
    q("cv3_009","Artículos sin PRECIOVENTA de venta definido","¿Qué artículos no tienen PRECIOVENTA de venta?","Artículos con PRECIOVENTA igual a cero o nulo.","SELECT A.CODIGO, A.NOMBRE, A.CODFAMILIA FROM ARTICULO A WHERE A.PRECIOVENTA IS NULL OR A.PRECIOVENTA=0 ORDER BY A.NOMBRE LIMIT 25","Calidad","Calidad","Alerta","Alto","Catálogo",""),
    q("cv3_010","Artículos sin PRECIOCOSTE definido","¿Qué artículos no tienen PRECIOCOSTE definido?","Artículos con PRECIOCOSTE igual a cero o nulo.","SELECT A.CODIGO, A.NOMBRE, A.CODFAMILIA FROM ARTICULO A WHERE A.PRECIOCOSTE IS NULL OR A.PRECIOCOSTE=0 ORDER BY A.NOMBRE LIMIT 25","Calidad","Calidad","Alerta","Alto","Catálogo",""),
    q("cv3_011","Clientes sin dirección registrada","¿Qué clientes no tienen dirección completa?","Clientes con dirección, población o CP vacíos.","SELECT C.CODIGO, COALESCE(C.NOMBRECOMERCIAL,C.RAZONSOCIAL) AS CLIENTE FROM CLIENTE C WHERE C.NULL IS NULL OR C.POBLACION IS NULL OR C.CP IS NULL ORDER BY CLIENTE LIMIT 25","Calidad","Calidad","Alerta","Medio","Datos maestros",""),
    q("cv3_012","Clientes sin CIF/NIF registrado","¿Qué clientes no tienen CIF o NIF?","Clientes con campo CIF/NIF vacío o nulo.","SELECT C.CODIGO, COALESCE(C.NOMBRECOMERCIAL,C.RAZONSOCIAL) AS CLIENTE FROM CLIENTE C WHERE C.NIF IS NULL OR C.NIF='' ORDER BY CLIENTE LIMIT 25","Calidad","Calidad","Alerta","Alto","Datos maestros",""),
    q("cv3_013","Proveedores sin CIF registrado","¿Qué proveedores no tienen CIF?","Proveedores con campo CIF vacío o nulo.","SELECT P.CODIGO, COALESCE(P.NOMBRECOMERCIAL, P.RAZONSOCIAL) FROM PROVEED P WHERE P.NIF IS NULL OR P.NIF='' ORDER BY COALESCE(P.NOMBRECOMERCIAL, P.RAZONSOCIAL) LIMIT 25","Calidad","Calidad","Alerta","Alto","Datos maestros",""),
    q("cv3_014","Artículos duplicados por nombre similar","¿Existen artículos con nombres muy similares?","Artículos con el mismo nombre exacto (posibles duplicados).","SELECT A.NOMBRE, COUNT(*) AS N_CODIGOS FROM ARTICULO A GROUP BY A.NOMBRE HAVING N_CODIGOS>1 ORDER BY N_CODIGOS DESC LIMIT 20","Calidad","Calidad","Alerta","Medio","Datos maestros",""),
    q("cv3_015","Líneas de factura con PRECIO cero","¿Existen líneas de factura con PRECIO cero?","Líneas en facturas TIPO=13 con PRECIO unitario cero.","SELECT D.CODIGO AS COD_FACTURA, D.FECHA, L.CODARTICULO AS COD_ART, A.NOMBRE, L.CANTIDAD FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO LEFT JOIN ARTICULO A ON A.CODIGO=L.CODARTICULO WHERE D.TIPO=13 AND (L.PRECIO IS NULL OR L.PRECIO=0) ORDER BY D.FECHA DESC LIMIT 25","Calidad","Calidad","Alerta","Alto","Anomalías",""),
    q("cv3_016","Líneas de factura con unidades negativas","¿Existen líneas de factura con unidades negativas?","Líneas en facturas TIPO=13 con unidades negativas.","SELECT D.CODIGO AS COD_FACTURA, D.FECHA, L.CODARTICULO AS COD_ART, A.NOMBRE, L.CANTIDAD FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO LEFT JOIN ARTICULO A ON A.CODIGO=L.CODARTICULO WHERE D.TIPO=13 AND L.CANTIDAD<0 ORDER BY D.FECHA DESC LIMIT 25","Calidad","Calidad","Alerta","Alto","Anomalías",""),
    q("cv3_017","Pedidos de venta sin servir con más de 30 días","¿Qué pedidos llevan más de 30 días sin servir?","Pedidos TIPO=1 sin albarán con más de 30 días de antigüedad.","SELECT D.CODIGO, D.FECHA, COALESCE(C.NOMBRECOMERCIAL,C.RAZONSOCIAL) AS CLIENTE, ROUND(JULIANDAY('now')-JULIANDAY(D.FECHA),0) AS DIAS_PENDIENTE FROM DOCCAB D LEFT JOIN CLIENTE C ON C.CODIGO=D.CODCLIENTE WHERE D.TIPO=1 AND D.FECHA<DATE('now','-30 days') AND D.CODIGO NOT IN (SELECT COALESCE(NULL,'') FROM DOCCAB WHERE TIPO=11) ORDER BY DIAS_PENDIENTE DESC LIMIT 20","Calidad","Calidad","Alerta","Alto","Pedidos",""),
    q("cv3_018","Albaranes sin facturar con más de 15 días","¿Qué albaranes llevan más de 15 días sin facturar?","Albaranes TIPO=11 sin factura asociada con más de 15 días.","SELECT D.CODIGO, D.FECHA, COALESCE(C.NOMBRECOMERCIAL,C.RAZONSOCIAL) AS CLIENTE, ROUND(JULIANDAY('now')-JULIANDAY(D.FECHA),0) AS DIAS_SIN_FACTURAR FROM DOCCAB D LEFT JOIN CLIENTE C ON C.CODIGO=D.CODCLIENTE WHERE D.TIPO=11 AND D.FECHA<DATE('now','-15 days') AND D.CODIGO NOT IN (SELECT COALESCE(NULL,'') FROM DOCCAB WHERE TIPO=13) ORDER BY DIAS_SIN_FACTURAR DESC LIMIT 20","Calidad","Calidad","Alerta","Alto","Facturación",""),
    q("cv3_019","Artículos con PRECIOVENTA de venta inferior al PRECIOCOSTE","¿Qué artículos se venden por debajo del PRECIOCOSTE?","Artículos con PRECIOVENTA de venta menor que el PRECIOCOSTE.","SELECT A.CODIGO, A.NOMBRE, ROUND(A.PRECIOVENTA,2) AS PRECIOVENTA_VENTA, ROUND(A.PRECIOCOSTE,2) AS COSTE, ROUND(A.PRECIOVENTA-A.PRECIOCOSTE,2) AS DIFERENCIA FROM ARTICULO A WHERE A.PRECIOVENTA>0 AND A.PRECIOCOSTE>0 AND A.PRECIOVENTA<A.PRECIOCOSTE ORDER BY DIFERENCIA ASC LIMIT 20","Calidad","Calidad","Alerta","Critico","Precios",""),
    q("cv3_020","Facturas con descuento superior al 50%","¿Existen facturas con descuentos excesivos?","Líneas de factura con descuento superior al 50%.","SELECT D.CODIGO AS COD_FACTURA, D.FECHA, COALESCE(C.NOMBRECOMERCIAL,C.RAZONSOCIAL) AS CLIENTE, L.CODARTICULO AS COD_ART, L.DESCUENTOS FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO LEFT JOIN CLIENTE C ON C.CODIGO=D.CODCLIENTE WHERE D.TIPO=13 AND L.DESCUENTOS>50 ORDER BY L.DESCUENTOS DESC LIMIT 25","Calidad","Calidad","Alerta","Alto","Descuentos",""),
    q("cv3_021","Artículos sin familia asignada","¿Qué artículos no tienen familia asignada?","Artículos con CODFAMILIA nulo o vacío.","SELECT A.CODIGO, A.NOMBRE FROM ARTICULO A WHERE A.CODFAMILIA IS NULL OR A.CODFAMILIA='' ORDER BY A.NOMBRE LIMIT 25","Calidad","Calidad","Alerta","Medio","Datos maestros",""),
    q("cv3_022","Clientes con NULL duplicado","¿Existen clientes con el mismo NULL?","Clientes con NULL repetido en la base de datos.","SELECT C.EMAIL, COUNT(*) AS N_CLIENTES FROM CLIENTE C WHERE C.EMAIL IS NOT NULL AND C.EMAIL<>'' GROUP BY C.EMAIL HAVING N_CLIENTES>1 ORDER BY N_CLIENTES DESC LIMIT 20","Calidad","Calidad","Alerta","Medio","Datos maestros",""),
    q("cv3_023","Facturas de compra sin proveedor asignado","¿Existen facturas de compra sin proveedor?","Facturas TIPO=20 con CODCLIENTE nulo.","SELECT CODIGO, FECHA FROM DOCCAB D WHERE D.TIPO=20 AND (D.CODCLIENTE IS NULL OR D.CODCLIENTE=0) ORDER BY FECHA DESC LIMIT 20","Calidad","Calidad","Alerta","Alto","Anomalías",""),
    q("cv3_024","Artículos con STOCKARTICULO en múltiples almacenes","¿Qué artículos tienen STOCKARTICULO repartido en más de un almacén?","Artículos con STOCKARTICULO positivo en más de un almacén.","SELECT A.CODIGO, A.NOMBRE, COUNT(DISTINCT '01') AS N_ALMACENES, ROUND(SUM(A.STOCKARTICULO),2) AS STOCK_TOTAL FROM ARTICULO A WHERE A.STOCKARTICULO>0 GROUP BY A.CODIGO, A.NOMBRE HAVING N_ALMACENES>1 ORDER BY N_ALMACENES DESC LIMIT 20","Calidad","Calidad","KPI","Medio","STOCKARTICULO",""),
    q("cv3_025","Pedidos de compra sin recibir con más de 30 días","¿Qué pedidos de compra llevan más de 30 días sin recibir?","Pedidos TIPO=4 sin albarán de compra con más de 30 días.","SELECT D.CODIGO, D.FECHA, COALESCE(COALESCE(P.NOMBRECOMERCIAL, P.RAZONSOCIAL),CAST(D.CODCLIENTE AS TEXT)) AS PROVEEDOR, ROUND(JULIANDAY('now')-JULIANDAY(D.FECHA),0) AS DIAS_PENDIENTE FROM DOCCAB D LEFT JOIN PROVEED P ON P.CODIGO=D.CODCLIENTE WHERE D.TIPO=4 AND D.FECHA<DATE('now','-30 days') AND D.CODIGO NOT IN (SELECT COALESCE(NULL,'') FROM DOCCAB WHERE TIPO=21) ORDER BY DIAS_PENDIENTE DESC LIMIT 20","Calidad","Calidad","Alerta","Alto","Compras",""),
    q("cv3_026","Artículos con rotación cero en el último año","¿Qué artículos no han tenido movimiento en el último año?","Artículos sin ninguna venta ni compra en 365 días.","SELECT A.CODIGO, A.NOMBRE, ROUND(SUM(A.STOCKARTICULO),2) AS STOCK_ACTUAL FROM ARTICULO A WHERE A.CODIGO NOT IN (SELECT DISTINCT L.CODARTICULO FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO WHERE D.FECHA>=DATE('now','-365 days')) GROUP BY A.CODIGO, A.NOMBRE HAVING STOCK_ACTUAL>0 ORDER BY STOCK_ACTUAL DESC LIMIT 25","Calidad","Calidad","Alerta","Alto","STOCKARTICULO",""),
    q("cv3_027","Facturas con fecha futura","¿Existen facturas con fecha posterior a hoy?","Facturas con fecha superior a la fecha actual.","SELECT CODIGO, FECHA, D.TIPO, D.CODCLIENTE FROM DOCCAB D WHERE FECHA>DATE('now') ORDER BY FECHA ASC LIMIT 20","Calidad","Calidad","Alerta","Critico","Anomalías",""),
    q("cv3_028","Documentos con fecha anterior a 2000","¿Existen documentos con fecha claramente errónea?","Documentos con fecha anterior al año 2000.","SELECT CODIGO, FECHA, D.TIPO FROM DOCCAB D WHERE FECHA<'2000-01-01' ORDER BY FECHA ASC LIMIT 20","Calidad","Calidad","Alerta","Critico","Anomalías",""),
    q("cv3_029","Artículos con PRECIOVENTA de compra superior al de venta","¿Qué artículos tienen PRECIOVENTA de compra mayor que el de venta?","Artículos donde el PRECIOVENTA de compra supera el PRECIOVENTA de venta.","SELECT A.CODIGO, A.NOMBRE, ROUND(A.PRECIOVENTA,2) AS PRECIOVENTA_VENTA, ROUND(A.PRECIOCOMPRA,2) AS PRECIOVENTA_COMPRA FROM ARTICULO A WHERE A.PRECIOVENTA>0 AND A.PRECIOCOMPRA>0 AND A.PRECIOCOMPRA>A.PRECIOVENTA ORDER BY (A.PRECIOCOMPRA-A.PRECIOVENTA) DESC LIMIT 20","Calidad","Calidad","Alerta","Alto","Precios",""),
    q("cv3_030","Clientes con más de una dirección de envío","¿Qué clientes tienen múltiples direcciones de envío?","Clientes con más de una dirección registrada.","SELECT C.CODIGO, COALESCE(C.NOMBRECOMERCIAL,C.RAZONSOCIAL) AS CLIENTE, COUNT(*) AS N_DIRECCIONES FROM CLIENTEDIR CD JOIN CLIENTE C ON C.CODIGO=CD.CODCLIENTE GROUP BY C.CODIGO, CLIENTE HAVING N_DIRECCIONES>1 ORDER BY N_DIRECCIONES DESC LIMIT 20","Calidad","Calidad","KPI","Bajo","Datos maestros",""),
    q("cv3_031","Artículos con descripción vacía","¿Qué artículos no tienen descripción?","Artículos con campo NOMBRE vacío o nulo.","SELECT A.CODIGO, A.CODFAMILIA FROM ARTICULO A WHERE A.NOMBRE IS NULL OR A.NOMBRE='' ORDER BY A.CODIGO LIMIT 25","Calidad","Calidad","Alerta","Medio","Datos maestros",""),
    q("cv3_032","Facturas con IMPORTEIVA no definido","¿Existen líneas de factura sin tipo de IMPORTEIVA?","Líneas de factura TIPO=13 con TIPOIVA nulo.","SELECT D.CODIGO AS COD_FACTURA, D.FECHA, L.CODARTICULO AS COD_ART, L.CANTIDAD, L.PRECIO FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO WHERE D.TIPO=13 AND (L.TIPOIVA IS NULL OR L.TIPOIVA=0) ORDER BY D.FECHA DESC LIMIT 25","Calidad","Calidad","Alerta","Alto","IMPORTEIVA",""),
    q("cv3_033","Clientes con teléfono duplicado","¿Existen clientes con el mismo teléfono?","Clientes con teléfono repetido en la base de datos.","SELECT C.TEL, COUNT(*) AS N_CLIENTES FROM CLIENTE C WHERE C.TEL IS NOT NULL AND C.TEL<>'' GROUP BY C.TEL HAVING N_CLIENTES>1 ORDER BY N_CLIENTES DESC LIMIT 20","Calidad","Calidad","Alerta","Bajo","Datos maestros",""),
    q("cv3_034","Artículos con STOCKARTICULO máximo superado","¿Qué artículos superan el STOCKARTICULO máximo definido?","Artículos con STOCKARTICULO actual superior al máximo permitido.","SELECT A.CODIGO, A.NOMBRE, ROUND(SUM(A.STOCKARTICULO),2) AS STOCK_ACTUAL, A.STOCKARTICULO FROM ARTICULO A JOIN ESTALMACEN E ON A.CODIGO=A.CODIGO WHERE A.STOCKARTICULO>0 GROUP BY A.CODIGO, A.NOMBRE, A.STOCKARTICULO HAVING STOCK_ACTUAL>A.STOCKARTICULO ORDER BY (STOCK_ACTUAL-A.STOCKARTICULO) DESC LIMIT 20","Calidad","Calidad","Alerta","Medio","STOCKARTICULO",""),
    q("cv3_035","Pedidos de venta con importe cero","¿Existen pedidos de venta con importe cero?","Pedidos TIPO=1 con importe total cero.","SELECT D.CODIGO, D.FECHA, D.CODCLIENTE FROM DOCCAB D LEFT JOIN (SELECT CODDOCUMENTO, SUM(CANTIDAD*PRECIO) AS IMP FROM DOCLIN GROUP BY CODDOCUMENTO) I ON I.CODDOCUMENTO=D.CODIGO WHERE D.TIPO=1 AND (I.IMP IS NULL OR I.IMP=0) ORDER BY D.FECHA DESC LIMIT 20","Calidad","Calidad","Alerta","Medio","Anomalías",""),
    q("cv3_036","Artículos con código de barras duplicado","¿Existen artículos con el mismo código de barras?","Artículos con CODIGOBARRAS repetido.","SELECT A.CODIGOBARRAS, COUNT(*) AS N_ARTICULOS FROM ARTICULO A WHERE A.CODIGOBARRAS IS NOT NULL AND A.CODIGOBARRAS<>'' GROUP BY A.CODIGOBARRAS HAVING N_ARTICULOS>1 ORDER BY N_ARTICULOS DESC LIMIT 20","Calidad","Calidad","Alerta","Alto","Datos maestros",""),
    q("cv3_037","Facturas de venta sin cliente asignado","¿Existen facturas de venta sin cliente?","Facturas TIPO=13 con CODCLIENTE nulo o cero.","SELECT CODIGO, FECHA FROM DOCCAB D WHERE D.TIPO=13 AND (D.CODCLIENTE IS NULL OR D.CODCLIENTE=0) ORDER BY FECHA DESC LIMIT 20","Calidad","Calidad","Alerta","Critico","Anomalías",""),
    q("cv3_038","Artículos con referencia de proveedor duplicada","¿Existen artículos con la misma referencia de proveedor?","Artículos con REFPROVEEDOR repetida.","SELECT A.REFPROVEEDOR, COUNT(*) AS N_ARTICULOS FROM ARTICULO A WHERE A.REFPROVEEDOR IS NOT NULL AND A.REFPROVEEDOR<>'' GROUP BY A.REFPROVEEDOR HAVING N_ARTICULOS>1 ORDER BY N_ARTICULOS DESC LIMIT 20","Calidad","Calidad","Alerta","Medio","Datos maestros",""),
    q("cv3_039","Clientes con CIF duplicado","¿Existen clientes con el mismo CIF?","Clientes con CIF repetido en la base de datos.","SELECT C.NIF, COUNT(*) AS N_CLIENTES FROM CLIENTE C WHERE C.NIF IS NOT NULL AND C.NIF<>'' GROUP BY C.NIF HAVING N_CLIENTES>1 ORDER BY N_CLIENTES DESC LIMIT 20","Calidad","Calidad","Alerta","Critico","Datos maestros",""),
    q("cv3_040","Proveedores con CIF duplicado","¿Existen proveedores con el mismo CIF?","Proveedores con CIF repetido en la base de datos.","SELECT P.NIF, COUNT(*) AS N_PROVEEDORES FROM PROVEED P WHERE P.NIF IS NOT NULL AND P.NIF<>'' GROUP BY P.NIF HAVING N_PROVEEDORES>1 ORDER BY N_PROVEEDORES DESC LIMIT 20","Calidad","Calidad","Alerta","Critico","Datos maestros",""),
    q("cv3_041","Artículos con PRECIOVENTA de venta sin actualizar en 1 año","¿Qué artículos no han actualizado su PRECIOVENTA en el último año?","Artículos cuyo PRECIOVENTA no ha cambiado en 365 días.","SELECT A.CODIGO, A.NOMBRE, A.PRECIOVENTA, NULL FROM ARTICULO A WHERE NULL IS NOT NULL AND NULL<DATE('now','-365 days') ORDER BY NULL ASC LIMIT 25","Calidad","Calidad","Alerta","Medio","Precios",""),
    q("cv3_042","Líneas de albarán sin artículo asignado","¿Existen líneas de albarán sin artículo?","Líneas en albaranes TIPO=11 con CODIGO de artículo nulo.","SELECT D.CODIGO AS COD_ALBARAN, D.FECHA, L.ROWID AS LINEA FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO WHERE D.TIPO=11 AND (L.CODARTICULO IS NULL OR L.CODARTICULO='') ORDER BY D.FECHA DESC LIMIT 20","Calidad","Calidad","Alerta","Alto","Anomalías",""),
    q("cv3_043","Artículos con STOCKARTICULO pero sin movimiento en 6 meses","¿Qué artículos tienen STOCKARTICULO pero no se han movido en 6 meses?","Artículos con STOCKARTICULO positivo sin ventas ni compras en 180 días.","SELECT A.CODIGO, A.NOMBRE, ROUND(SUM(A.STOCKARTICULO),2) AS STOCK_ACTUAL, ROUND(SUM(A.STOCKARTICULO)*A.PRECIOCOSTE,2) AS VALOR_INMOVILIZADO FROM ARTICULO A JOIN ESTALMACEN E ON A.CODIGO=A.CODIGO WHERE A.STOCKARTICULO>0 AND A.CODIGO NOT IN (SELECT DISTINCT L.CODARTICULO FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO WHERE D.FECHA>=DATE('now','-180 days')) GROUP BY A.CODIGO, A.NOMBRE, A.PRECIOCOSTE ORDER BY VALOR_INMOVILIZADO DESC LIMIT 25","Calidad","Calidad","Alerta","Alto","STOCKARTICULO",""),
    q("cv3_044","Facturas con número de serie duplicado","¿Existen facturas con el mismo número de serie?","Facturas TIPO=13 con NUMSERIE repetido.","SELECT D.SERIE, NULL, COUNT(*) AS N_FACTURAS FROM DOCCAB D WHERE D.TIPO=13 AND NULL IS NOT NULL GROUP BY D.SERIE, NULL HAVING N_FACTURAS>1 ORDER BY N_FACTURAS DESC LIMIT 20","Calidad","Calidad","Alerta","Critico","Anomalías",""),
    q("cv3_045","Artículos con margen negativo en ventas","¿Qué artículos se venden con margen negativo?","Artículos donde el PRECIO de venta en facturas es inferior al PRECIOCOSTE.","SELECT L.CODARTICULO AS COD_ART, A.NOMBRE, ROUND(AVG(L.PRECIO),2) AS PRECIO_MEDIO, ROUND(A.PRECIOCOSTE,2) AS COSTE, ROUND(AVG(L.PRECIO)-A.PRECIOCOSTE,2) AS MARGEN FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO LEFT JOIN ARTICULO A ON A.CODIGO=L.CODARTICULO WHERE D.TIPO=13 AND A.PRECIOCOSTE>0 AND L.PRECIO>0 GROUP BY L.CODARTICULO, A.NOMBRE, A.PRECIOCOSTE HAVING MARGEN<0 ORDER BY MARGEN ASC LIMIT 20","Calidad","Calidad","Alerta","Critico","Precios",""),
    q("cv3_046","Clientes sin forma de pago asignada","¿Qué clientes no tienen forma de pago definida?","Clientes con CODFORMAPAGO nulo o vacío.","SELECT C.CODIGO, COALESCE(C.NOMBRECOMERCIAL,C.RAZONSOCIAL) AS CLIENTE FROM CLIENTE C WHERE C.CODFORMAPAGO IS NULL OR C.CODFORMAPAGO='' ORDER BY CLIENTE LIMIT 25","Calidad","Calidad","Alerta","Medio","Datos maestros",""),
    q("cv3_047","Artículos con unidad de medida no definida","¿Qué artículos no tienen unidad de medida?","Artículos con CODUNIDAD nulo o vacío.","SELECT A.CODIGO, A.NOMBRE FROM ARTICULO A WHERE A.CODUNIDAD IS NULL OR A.CODUNIDAD='' ORDER BY A.NOMBRE LIMIT 25","Calidad","Calidad","Alerta","Bajo","Datos maestros",""),
    q("cv3_048","Resumen de alertas de calidad de datos","¿Cuántas alertas de calidad de datos hay actualmente?","Resumen de incidencias de calidad detectadas.","SELECT (SELECT COUNT(*) FROM ARTICULO WHERE PRECIOVENTA IS NULL OR PRECIOVENTA=0) AS ARTS_SIN_PRECIOVENTA, (SELECT COUNT(*) FROM ARTICULO WHERE PRECIOCOSTE IS NULL OR PRECIOCOSTE=0) AS ARTS_SIN_PRECIOCOSTE, (SELECT COUNT(*) FROM CLIENTE WHERE CIF IS NULL OR CIF='') AS CLIENTES_SIN_CIF, (SELECT COUNT(*) FROM ARTICULO A JOIN ESTALMACEN E ON A.CODIGO=A.CODIGO WHERE A.STOCKARTICULO>0 GROUP BY A.CODIGO HAVING SUM(A.STOCKARTICULO)<A.STOCKARTICULO) AS ARTS_BAJO_MINIMO","Calidad","Calidad","KPI","Critico","Resumen",""),
    q("cv3_049","Artículos con PRECIOVENTA actualizado en el último mes","¿Qué artículos han actualizado su PRECIOVENTA en el último mes?","Artículos con NULL en los últimos 30 días.","SELECT A.CODIGO, A.NOMBRE, ROUND(A.PRECIOVENTA,2) AS PRECIOVENTA_ACTUAL, NULL FROM ARTICULO A WHERE NULL>=DATE('now','-30 days') ORDER BY NULL DESC LIMIT 25","Calidad","Calidad","KPI","Medio","Precios",""),
    q("cv3_050","Resumen anual de calidad","¿Cuál es el resumen anual de indicadores de calidad?","Devoluciones, anomalías y alertas del año en curso.","SELECT CAST(STRFTIME('%Y','now') AS TEXT) AS EJERCICIO, (SELECT COUNT(*) FROM DOCCAB WHERE TIPO=14 AND SUBSTR(FECHA,1,4)=CAST(STRFTIME('%Y','now') AS TEXT)) AS N_ABONOS_ANIO, (SELECT ROUND(SUM(L.CANTIDAD*L.PRECIO),2) FROM DOCLIN L JOIN DOCCAB D ON D.CODIGO=L.CODDOCUMENTO WHERE D.TIPO=14 AND SUBSTR(D.FECHA,1,4)=CAST(STRFTIME('%Y','now') AS TEXT)) AS IMPORTE_ABONOS, (SELECT COUNT(*) FROM ARTICULO A JOIN ESTALMACEN E ON A.CODIGO=A.CODIGO WHERE A.STOCKARTICULO>0 AND A.STOCKARTICULO<A.STOCKARTICULO) AS ARTS_BAJO_MINIMO","Calidad","Calidad","KPI","Critico","Resumen",""),
]
